// instanceId=31 = NSM_INSTANCE_MAX → boundary: encode succeeds
TEST(NsmTotalMemoryTest, GenRequestMsg_MaxValidInstanceId_ReturnsRequest)
{
    NsmTotalMemory sensor("TotalMem3", "NSM_Memory");

